#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

struct FunctionEntry { std::uint64_t start; std::uint64_t size; std::string name; };

class FunctionMap
{
public:
    explicit FunctionMap(const std::vector<FunctionEntry>& entries)
    {
        for (const FunctionEntry& e : entries)
        {
            if (e.size == 0) continue;
            bool overlaps{ false };
            for (const FunctionEntry& k : m_entries)
                if (e.start < k.start + k.size && k.start < e.start + e.size) overlaps = true;
            if (!overlaps) m_entries.push_back(e);
        }
        std::sort(m_entries.begin(), m_entries.end(),
                  [](const FunctionEntry& a, const FunctionEntry& b) { return a.start < b.start; });
    }

    std::string describe(std::uint64_t address) const
    {
        // The first entry starting after the address; the one before it is the candidate.
        auto it{ std::upper_bound(m_entries.begin(), m_entries.end(), address,
                                  [](std::uint64_t a, const FunctionEntry& e) { return a < e.start; }) };
        if (it == m_entries.begin()) return "?";
        --it;
        const std::uint64_t offset{ address - it->start };
        if (offset >= it->size) return "?";
        if (offset == 0) return it->name;
        char buffer[32];
        std::snprintf(buffer, sizeof buffer, "+0x%llx", static_cast<unsigned long long>(offset));
        return it->name + buffer;
    }

    std::size_t count() const { return m_entries.size(); }

private:
    std::vector<FunctionEntry> m_entries;
};

unitTests:
const FunctionMap map{ { { 0x140001200, 0x80, "parseHeader" }, { 0x140001000, 0x100, "main" }, { 0x140001100, 0x40, "readFile" } } };
TEST("a function's first byte") { CHECK_EQ(map.describe(0x140001000), std::string("main")); CHECK_EQ(map.describe(0x140001200), std::string("parseHeader")); }
TEST("inside a function") { CHECK_EQ(map.describe(0x14000101f), std::string("main+0x1f")); CHECK_EQ(map.describe(0x14000113f), std::string("readFile+0x3f")); }
TEST("in a gap") { CHECK_EQ(map.describe(0x140001140), std::string("?")); CHECK_EQ(map.describe(0x140001280), std::string("?")); }
TEST("before everything") { CHECK_EQ(map.describe(0x1000), std::string("?")); CHECK_EQ(map.describe(0), std::string("?")); }
TEST("overlaps keep the earlier entry")
{
    const FunctionMap m{ { { 0x2000, 0x20, "first" }, { 0x2010, 0x20, "clash" }, { 0x2020, 0x10, "next" } } };
    CHECK_EQ(m.count(), std::size_t{ 2 });
    CHECK_EQ(m.describe(0x2018), std::string("first+0x18"));
    CHECK_EQ(m.describe(0x2028), std::string("next+0x8"));
}
TEST("counts") { CHECK_EQ(map.count(), std::size_t{ 3 }); CHECK_EQ(FunctionMap({}).count(), std::size_t{ 0 }); CHECK_EQ(FunctionMap({}).describe(5), std::string("?")); }

